from qb import q, write

QA = ["python-developer", "backend-developer", "full-stack-developer"]
ITEMS = [
    q("testing", "easy", ["fundamentals"], "What is the difference between verification and validation, and between a bug, a defect and a failure?", "Verification checks that the product is built right according to the specification, and validation checks that the right product is built for the user's need. A defect is a flaw in the code or design, which can cause a failure, the visible wrong behaviour. A bug is the everyday word for a defect.", ["Built right vs right product", "Defect causes failure", "Different questions"], ["Give an example where tests pass but the product is wrong."]),
    q("testing", "easy", ["test-design"], "How do you write good test cases for a login page?", "Cover valid login, wrong password, unknown user, empty fields, locked accounts, password rules, session timeout, logout and security cases such as SQL injection text, plus usability and accessibility. Each case states steps, data and the expected result.", ["Positive and negative cases", "Boundaries and security cases", "Clear steps and expected results"], ["Which cases would you automate first?"]),
    q("testing", "medium", ["techniques"], "Explain equivalence partitioning and boundary value analysis with an example of an age field that accepts 18 to 60.", "Equivalence partitioning groups inputs that behave the same, such as below 18, 18 to 60 and above 60, and tests one from each. Boundary value analysis tests at the edges, 17, 18, 19, 59, 60 and 61, where bugs concentrate.", ["Partitions of equal behaviour", "Edges: 17, 18, 60, 61", "Fewer, smarter tests"], ["How do you test a field with no stated limits?"]),
    q("testing", "medium", ["bug-reports"], "What does a good bug report contain and how do you decide its severity and priority?", "A good report has a clear title, steps to reproduce, expected and actual results, environment, evidence such as screenshots or logs and the version. Severity is the technical impact, priority is how soon the business wants it fixed, and they can differ.", ["Reproducible steps and evidence", "Severity vs priority", "Environment and version"], ["Give a high severity but low priority example."]),
    q("testing", "medium", ["strategy"], "What is the test pyramid and why is a suite made only of end-to-end tests a problem?", "The pyramid has many fast unit tests, fewer integration tests and a small number of end-to-end tests. Too many end-to-end tests are slow, fragile and hard to debug, so failures take long to diagnose.", ["Layers and proportions", "Cost of UI tests", "Fast feedback"], ["Where do API tests fit?"]),
    q("testing", "hard", ["risk"], "You have two days to test a release that normally takes a week. How do you decide what to test?", "Assess risk by the impact and likelihood of failure and by what changed, test critical user journeys and changed areas first, run automated regression, agree with stakeholders on what is skipped and report the remaining risk clearly.", ["Risk-based prioritisation", "Critical paths and changes", "Communicate remaining risk"], ["How would you decide whether to delay the release?"]),
    q("automation", "easy", ["selenium"], "What is Selenium and what makes UI automation tests flaky?", "Selenium controls a browser to run UI tests automatically. Flakiness comes from timing, such as acting before an element is ready, unstable selectors, shared or changing test data and environment differences.", ["Browser automation", "Timing and selectors", "Test data and environment"], ["How do waits help?"]),
    q("automation", "medium", ["python-testing"], "How would you automate API tests in Python and what would each test check?", "Use pytest with the requests library, send calls to endpoints and assert the status code, response body and headers, and the effect on the database for writes. Use fixtures for setup and parametrised tests for many inputs.", ["pytest and requests", "Status, body, side effects", "Fixtures and parametrisation"], ["How do you test an endpoint that needs a login?"]),
    q("automation", "medium", ["page-object"], "What is the page object pattern and why does it help?", "It wraps each page's elements and actions in a class so tests call methods such as login, not raw selectors. When the page changes you fix one class instead of many tests, which reduces duplication and maintenance.", ["Page as a class", "Tests use actions", "One place to fix changes"], ["What is a downside?"]),
    q("automation", "hard", ["ci"], "How do you integrate automated tests into a CI pipeline and handle a test that fails randomly?", "Run fast tests on every push and slower suites on merges or nightly, publish reports and block merges on failures. For a flaky test find the cause, such as timing or shared data, fix or quarantine it with a ticket instead of ignoring failures.", ["Staged test runs", "Reports and gates", "Fix or quarantine flaky tests"], ["How do you measure flakiness?"]),
    q("automation", "medium", ["performance"], "How would you do a basic load test of an API and which numbers do you report?", "Use a tool such as JMeter or Locust to simulate users ramping up, measure response time percentiles, throughput, error rate and resource use, and find the point where performance degrades. Test in an environment like production.", ["Ramp up simulated users", "Percentiles, throughput, errors", "Realistic environment"], ["Why use the 95th percentile and not the average?"]),
    q("security", "easy", ["owasp"], "Name three common web vulnerabilities from the OWASP Top 10 and how you would test for them.", "SQL injection by entering query fragments in inputs and observing errors or behaviour, cross-site scripting by submitting script text and checking if it runs, and broken access control by trying to open another user's data or admin pages. Always test only with permission.", ["Injection, XSS, access control", "Simple test approaches", "Only with permission"], ["How do developers prevent each one?"]),
    q("security", "medium", ["authentication"], "How would you test the security of a password reset feature?", "Check that reset links are random, expire and work once, responses do not reveal whether an email exists, attempts are rate limited, the old password stops working and the link is not leaked in logs or referrers.", ["Random, expiring, single-use tokens", "No account enumeration", "Rate limits"], ["What is account enumeration?"]),
    q("security", "medium", ["pen-testing"], "What are the phases of a penetration test and how does it differ from a vulnerability scan?", "A test typically includes scoping and permission, reconnaissance, scanning, exploitation to prove impact, reporting and retesting. A scan automatically lists known weaknesses, while a penetration test uses manual skill to chain and exploit them.", ["Phases from scope to retest", "Scan lists, test exploits", "Written permission first"], ["Why is a written scope essential?"]),
    q("security", "hard", ["api-security"], "What security issues would you look for in a REST API and how would you test them?", "Look for missing authentication, broken object-level authorisation, excessive data in responses, weak rate limiting, missing input validation and verbose errors. Test by calling endpoints without tokens, with other users' ids and with malformed input.", ["Authentication and object-level authorisation", "Data exposure and rate limits", "Malformed input"], ["What is IDOR?"]),
    q("security", "medium", ["encryption"], "What is the difference between hashing, encryption and encoding, with a use for each?", "Hashing is one-way and used for passwords and integrity, encryption is reversible with a key and protects confidentiality, and encoding such as Base64 only changes representation and gives no secrecy.", ["One-way vs reversible vs no secrecy", "Password hashing", "Base64 is not security"], ["Why is Base64 never a protection?"]),
    q("sql", "medium", ["test-data"], "How would you use SQL to verify that a data migration moved all records correctly?", "Compare row counts and key totals between source and target, check for missing or duplicate keys with joins, compare sample records field by field and look for null or truncated values.", ["Counts and totals", "Anti-joins for missing keys", "Field-level sampling"], ["How would you automate the checks?"]),
    q("python", "medium", ["python", "scripting"], "Write the idea of a Python script that checks a list of URLs and reports which return errors or are slow.", "Loop over the URLs with the requests library using timeouts, record the status code and elapsed time, flag errors and slow responses, use concurrency for many URLs and write the results to a file.", ["requests with timeouts", "Record status and time", "Concurrency and a report"], ["How would you avoid being blocked as a bot?"]),
    q("agile-qa", "easy", ["agile"], "What is the role of QA in an Agile team and what is shift-left testing?", "QA joins from the start, clarifying requirements, writing acceptance criteria, testing continuously and automating regression. Shift-left means testing earlier, such as reviewing requirements and unit testing, because late defects cost more to fix.", ["QA throughout the sprint", "Acceptance criteria", "Earlier is cheaper"], ["What is a definition of done?"]),
    q("api-testing", "medium", ["postman"], "How do you test an API that returns a list with pagination and filters?", "Check the default page, page size limits, first and last page, an out-of-range page, each filter alone and combined, sorting, empty results and invalid parameters, and verify counts against the database.", ["Pagination boundaries", "Filter combinations", "Invalid parameters and counts"], ["How would you check performance for deep pages?"]),
    q("kual-scenario", "medium", ["defects"], "Scenario: a developer says your bug is not a bug and works as designed. What do you do?", "Check the requirement or specification, show the evidence and the user impact, discuss calmly with the developer and product owner to confirm the intended behaviour, and record the outcome, either fixing it or updating the documentation.", ["Check the requirement", "Show evidence and impact", "Agree and record"], ["What if there is no written requirement?"], kind="scenario"),
    q("kual-scenario", "hard", ["automation-design"], "Scenario: a team wants to automate 2,000 manual test cases next quarter. How do you plan it?", "Prioritise stable, high-value and repeated cases, automate at the lowest sensible level, build a maintainable framework with reporting and CI, track coverage and maintenance cost and keep exploratory testing manual. Do not try to automate everything.", ["Prioritise by value and stability", "Right level and framework", "Keep exploratory testing"], ["How do you measure return on automation?"], kind="scenario"),
    q("kual-scenario", "easy", ["communication"], "Scenario: you find a critical bug one hour before release. What do you do?", "Verify and reproduce it quickly, document the impact, inform the release owner and team immediately with facts, suggest options such as a fix, a workaround or a delay and let the decision-maker choose.", ["Verify and document", "Escalate immediately", "Offer options"], ["What would you do afterwards?"], kind="scenario"),
    q("testing", "easy", ["regression"], "What is regression testing and smoke testing and when do you run each?", "Smoke testing is a quick check that the main functions work after a new build, deciding whether deeper testing is worthwhile. Regression testing reruns existing tests after changes to confirm old behaviour still works, and is best automated.", ["Quick build check vs broad re-check", "Run smoke first", "Automate regression"], ["What would you include in a smoke suite?"]),
    q("project", "easy", ["projects"], "Describe a testing, automation or security exercise you did. What did you find and how did you report it?", "A strong answer describes the target and scope, what you tested and how, a real finding with its impact, how you reported it and what you learned.", ["Scope and method", "A real finding and impact", "Clear reporting"], ["What would you automate from it?"], kind="scenario", roles=QA),
]


def build():
    return write("kualitatem", QA, ITEMS)


if __name__ == "__main__":
    build()
